import json,os,subprocess,sys
from pathlib import Path
root=Path('/kaggle/working/payload');root.mkdir(exist_ok=True)
FILES={'src/p3a/eval/reliability_cost.py': '"""Measured computation and recorded-marker proxies, never clinical throughput."""\nimport time\nimport numpy as np\n\ndef marker_duration_seconds(onsets,fs,epoch_seconds=.8):\n    events=np.asarray(onsets,dtype=float)\n    if events.ndim!=1 or len(events)<2 or not np.isfinite(events).all() or not np.isfinite(fs) or fs<=0 or epoch_seconds<=0:\n        raise ValueError(\'finite event sequence and positive sampling/epoch duration required\')\n    # Preserve stored order, including documented timestamp reversals.\n    duration=float((events[-1]-events[0])/fs+epoch_seconds)\n    if duration<=0:raise ValueError(\'nonpositive recorded first-to-last duration\')\n    return duration\n\ndef measure_inference(callback,synchronize,warmup=5,repeats=30):\n    if warmup<0 or repeats<2:raise ValueError(\'nonnegative warmup and at least2 repeats required\')\n    for _ in range(warmup):callback();synchronize()\n    elapsed=[]\n    for _ in range(repeats):\n        synchronize();start=time.perf_counter();callback();synchronize()\n        elapsed.append(time.perf_counter()-start)\n    return dict(warmup=warmup,repeats=repeats,seconds=elapsed,median_seconds=float(np.median(elapsed)),p95_seconds=float(np.quantile(elapsed,.95)),scope=\'batch1 computation only; not physical latency or clinical spelling throughput\')\n', 'tests/test_reliability_cost.py': "import pytest\nfrom p3a.eval.reliability_cost import marker_duration_seconds,measure_inference\n\ndef test_marker_proxy_preserves_stored_endpoints():\n    assert marker_duration_seconds([100,90,300],1000)==pytest.approx(1.)\n    with pytest.raises(ValueError):marker_duration_seconds([100,200],0)\n    with pytest.raises(ValueError):marker_duration_seconds([float('nan'),200],1000)\n\ndef test_timing_calls_and_scope():\n    calls=[];sync=[]\n    r=measure_inference(lambda:calls.append(1),lambda:sync.append(1),warmup=2,repeats=3)\n    assert len(calls)==5 and len(sync)==8\n    assert len(r['seconds'])==3 and r['median_seconds']>=0 and r['p95_seconds']>=0\n    assert 'not physical' in r['scope']\n"}
for name,source in FILES.items():
    p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(source)
os.environ['PYTHONPATH']=str(root/'src')
out=Path('/kaggle/working/out');out.mkdir(exist_ok=True)
r=subprocess.run([sys.executable,'-m','pytest','-q',str(root/'tests/test_reliability_cost.py')],capture_output=True,text=True)
(out/'pytest.txt').write_text(r.stdout+r.stderr)
(out/'scope.json').write_text(json.dumps(dict(seed=20261013,git_commit='fd9ccc7',scope='synthetic timing call/order and marker proxy checks; no performance result',returncode=r.returncode),indent=2))
print(r.stdout+r.stderr);assert r.returncode==0
